class Solution {
  public int maxProduct(int n) {
    int first = 0, second = 0;
    for (; n > 0; n /= 10) {
      int d = n % 10;
      if (d > first) {
        second = first;
        first = d;
      } else if (d > second) {
        second = d;
      }
    }
    return first * second;
  }
}
